#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
int LLVMFuzzerTestOneInput(const uint8_t*, size_t);
int main(int argc, char** argv) {
    if(argc < 2) return 2;
    FILE* f = fopen(argv[1], "rb");
    if(!f) return 2;
    if(fseek(f, 0, SEEK_END) != 0) return 2;
    long n = ftell(f);
    if(n < 0) return 2;
    rewind(f);
    unsigned char* p = (unsigned char*) malloc((size_t)n);
    if(n > 0 && p == NULL) return 2;
    if(n > 0 && fread(p, 1, (size_t)n, f) != (size_t)n) return 2;
    fclose(f);
    int r = LLVMFuzzerTestOneInput(p, (size_t)n);
    free(p);
    return r;
}
EOF
